const result = $input.first().json;
const config = result.config || {};
const entries = config.ats || [];

return entries.map(e => ({
  json: {
    id: e.provider + ':' + e.token,
    provider: e.provider,
    token: e.token,
    company: e.company
  }
}));

function stripHtml(html) {
  if (!html) return '';
  let s = html;
  s = s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
  s = s.replace(/<[^>]+>/g, ' ');
  s = s.replace(/&nbsp;/g, ' ');
  return s.replace(/\s+/g, ' ').trim();
}

const source = $('Get Active ATS Sources').item.json;
const resp = $input.item.json;

if (resp.statusCode !== 200) {
  return { json: { source_id: source.id, company: source.company, provider: 'greenhouse', fetch_failed: true, statusCode: resp.statusCode, postings: [] } };
}

let data;
try {
  const raw = resp.body !== undefined ? resp.body : resp.data;
  data = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return { json: { source_id: source.id, company: source.company, provider: 'greenhouse', fetch_failed: true, parse_error: true, postings: [] } };
}

const jobs = data.jobs || [];
const postings = jobs.map(j => ({
  company: source.company,
  role: j.title,
  location: (j.location && j.location.name) || null,
  employment_type: null,
  apply_url: j.absolute_url,
  source: 'greenhouse',
  source_id: source.id,
  description: stripHtml(j.content),
  posted_date: j.updated_at || null
}));

return { json: { source_id: source.id, company: source.company, provider: 'greenhouse', postings } };

function mapCommitment(c) {
  if (!c) return null;
  const s = c.toLowerCase();
  if (s.includes('intern')) return 'internship';
  if (s.includes('full')) return 'full_time';
  if (s.includes('part')) return 'part_time';
  if (s.includes('contract')) return 'contract';
  return s.replace(/\s+/g, '_');
}

const source = $('Get Active ATS Sources').item.json;
const resp = $input.item.json;

if (resp.statusCode !== 200) {
  return { json: { source_id: source.id, company: source.company, provider: 'lever', fetch_failed: true, statusCode: resp.statusCode, postings: [] } };
}

let jobs;
try {
  const raw = resp.body !== undefined ? resp.body : resp.data;
  jobs = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return { json: { source_id: source.id, company: source.company, provider: 'lever', fetch_failed: true, parse_error: true, postings: [] } };
}
if (!Array.isArray(jobs)) jobs = [];

const postings = jobs.map(j => ({
  company: source.company,
  role: j.text,
  location: (j.categories && j.categories.location) || null,
  employment_type: mapCommitment(j.categories && j.categories.commitment),
  apply_url: j.hostedUrl || j.applyUrl,
  source: 'lever',
  source_id: source.id,
  description: (j.descriptionPlain || '').replace(/\s+/g, ' ').trim(),
  posted_date: j.createdAt ? new Date(j.createdAt).toISOString() : null
}));

return { json: { source_id: source.id, company: source.company, provider: 'lever', postings } };

function mapEmploymentType(t) {
  if (!t) return null;
  const map = { FullTime: 'full_time', PartTime: 'part_time', Intern: 'internship', Contract: 'contract', Temporary: 'contract' };
  return map[t] || t.toLowerCase();
}

const source = $('Get Active ATS Sources').item.json;
const resp = $input.item.json;

if (resp.statusCode !== 200) {
  return { json: { source_id: source.id, company: source.company, provider: 'ashby', fetch_failed: true, statusCode: resp.statusCode, postings: [] } };
}

let data;
try {
  const raw = resp.body !== undefined ? resp.body : resp.data;
  data = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return { json: { source_id: source.id, company: source.company, provider: 'ashby', fetch_failed: true, parse_error: true, postings: [] } };
}

const jobs = data.jobs || [];
const postings = jobs.map(j => ({
  company: source.company,
  role: j.title,
  location: j.location || null,
  employment_type: mapEmploymentType(j.employmentType),
  apply_url: j.jobUrl || j.applyUrl,
  source: 'ashby',
  source_id: source.id,
  description: (j.descriptionPlain || '').replace(/\s+/g, ' ').trim(),
  posted_date: j.publishedAt || null
}));

return { json: { source_id: source.id, company: source.company, provider: 'ashby', postings } };

const dedupOutputs = $input.all();
const originals = $('Call WF-L1').all();
const toScore = [];
for (let i = 0; i < dedupOutputs.length; i++) {
  if (dedupOutputs[i].json.was_inserted === true) {
    toScore.push({ json: originals[i].json });
  }
}
return toScore;

// Seed one entry per source that was actually queried this run, so a
// provider returning zero postings (empty result OR fetch failure) still
// gets a runs row instead of silently vanishing (Phase 3 zero-result gap).
const sources = $('Get Active ATS Sources').all().map(i => i.json);
const bySource = new Map();
for (const s of sources) {
  bySource.set(s.id, { source_id: s.id, provider: s.provider, fetched: 0, new_count: 0 });
}

for (const item of $input.all()) {
  const sid = item.json.source_id;
  if (!bySource.has(sid)) {
    bySource.set(sid, { source_id: sid, provider: 'unknown', fetched: 0, new_count: 0 });
  }
  const agg = bySource.get(sid);
  agg.fetched += 1;
  if (item.json.was_inserted === true) agg.new_count += 1;
}

return Array.from(bySource.values()).map(v => ({
  json: { ...v, deduped: v.fetched - v.new_count }
}));

// Runs after every run/streak row is already committed, so an alarm here
// never blocks the writes that already happened -- matches WF-0's pattern
// of throwing only after Write Run has succeeded.
const offenders = $input.all()
  .map(i => i.json)
  .filter(s => s.consecutive_zero >= 2);

if (offenders.length > 0) {
  const detail = offenders
    .map(s => `${s.source_id} (${s.provider}): ${s.consecutive_zero} consecutive zero-result runs`)
    .join('; ');
  throw new Error('WF-1: source(s) returned zero postings 2+ runs in a row: ' + detail);
}

return [{ json: { ok: true } }];
